// Customers and CRM profiles.
// Owner: Agent B2 (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
import { z } from 'zod';
import { isoDate, optionalText, uuid } from './common';

export const customersContractsVersion = 1 as const;

const tag = z.string().trim().toLowerCase().min(1).max(40).regex(/^[\p{L}\p{N} _-]+$/u, 'letters, digits, spaces, _ and -');

export const customerListQuery = z.object({
  q: z.string().trim().max(120).optional(),
  tag: tag.optional(),
  consent: z.enum(['granted', 'not_granted']).optional(),
  lastOrderBefore: isoDate.optional(),
  lastOrderAfter: isoDate.optional(),
  minOrders: z.coerce.number().int().min(0).max(100000).optional(),
  minSpendMinor: z.coerce.number().int().min(0).max(1e13).optional(),
  branchId: uuid.optional(),
  includeAnonymised: z.enum(['true', 'false']).optional(),
  sort: z.enum(['last_order', 'spend', 'orders', 'name', 'created']).default('last_order'),
  limit: z.coerce.number().int().min(1).max(200).default(50),
  /** Opaque keyset cursor from the previous page (`k…`); plain digits are a legacy offset still accepted. */
  cursor: z.string().regex(/^(\d{1,9}|k[A-Za-z0-9_-]{1,600})$/).optional(),
});
export type CustomerListQuery = z.infer<typeof customerListQuery>;

export const customerUpdate = z.object({
  displayName: optionalText(120),
  tags: z.array(tag).max(30).optional(),
  notes: optionalText(2000),
}).refine((v) => Object.keys(v).length > 0, 'nothing to update');

/** Where a consent decision came from. Consent is never inferred; staff record what the guest said or signed. */
export const CONSENT_SOURCES = ['staff_verbal', 'written_form', 'customer_request', 'unsubscribe_request', 'import', 'other'] as const;
export const consentUpdate = z.object({
  granted: z.boolean(),
  source: z.enum(CONSENT_SOURCES),
  note: optionalText(300),
});

export const anonymiseInput = z.object({
  confirm: z.literal(true),
  reason: z.string().trim().min(3).max(300),
});

export const mergeInput = z.object({ duplicateId: uuid });

export interface CustomerSummary {
  id: string; displayName: string | null; phone: string | null; email: string | null; locale: string;
  marketingConsent: boolean; marketingConsentAt: string | null; marketingConsentSource: string | null;
  tags: string[]; orderCount: number; totalSpendMinor: number; lastOrderAt: string | null; firstOrderAt: string | null;
  anonymisedAt: string | null; createdAt: string;
}

export interface CustomerProfile extends CustomerSummary {
  notes: string | null;
  identities: Array<{ id: string; kind: string; value: string; verifiedAt: string | null }>;
  addresses: Array<{ id: string; label: string | null; line1: string; area: string | null; city: string | null; notes: string | null }>;
  totals: { orderCount: number; cancelledCount: number; grossMinor: number; refundedMinor: number; netMinor: number; averageOrderMinor: number; currency: string };
  orders: Array<{ id: string; number: string; branchId: string; channel: string; fulfillment: string; status: string; paymentStatus: string; totalMinor: number; refundedMinor: number; placedAt: string }>;
  reservations: Array<{ id: string; code: string; branchId: string; startsAt: string; partySize: number; status: string }>;
  consentHistory: Array<{ id: string; granted: boolean; source: string; note: string | null; actor: string | null; occurredAt: string }>;
}
